"use client";

import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import plan from "./career-plan.json";
import { learningProgressChart, type LearningEvent, type LearningState } from "../lib/learning-progress-chart";
import "./learning-progress-overview.css";

const groups = [
  { id: "foundation", title: "Fachgrundlagen", ids: plan.weeks.flatMap(w => w.days.filter(d => d.core).flatMap(d => d.lessonIds)), href: "/learning-lab" },
  { id: "portfolio", title: "Portfolio und Beruf", ids: plan.weeks.flatMap(w => w.days.filter(d => !d.core).flatMap(d => d.lessonIds)), href: "/career#week-9" },
  { id: "german", title: "Deutschtraining", ids: plan.weeks.flatMap(w => w.german?.lessonIds ?? []), href: "/career#deutsch" },
];
const allIds = groups.flatMap(group => group.ids);
type Snapshot = { states: Record<string, LearningState>; events: LearningEvent[] };
const shortDate = (date: string) => new Intl.DateTimeFormat("de-DE", { day: "numeric", month: "short", timeZone: "Europe/Berlin" }).format(new Date(date + "T12:00:00Z"));

export default function LearningProgressOverview() {
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [connection, setConnection] = useState<"loading" | "live" | "offline">("loading");
  const [now, setNow] = useState<Date | null>(null);
  const sync = useCallback(async (signal: AbortSignal) => {
    try {
      const response = await fetch("/api/learning-lab/progress", { cache: "no-store", signal });
      const data = await response.json() as Partial<Snapshot> & { roadmapId?: string; completionBasis?: string };
      if (!response.ok || data.roadmapId !== "thesis-predefense-2026" || data.completionBasis !== "practice" || !data.states || !Array.isArray(data.events) || allIds.some(id => typeof data.states?.[id]?.practiced !== "boolean") || !data.events.every(event => event && [event.id, event.lessonId, event.kind, event.at].every(value => typeof value === "string"))) throw new Error("Lernstand nicht verfügbar");
      setSnapshot({ states: data.states, events: data.events }); setNow(new Date()); setConnection("live");
    } catch { if (!signal.aborted || signal.reason?.name === "TimeoutError") setConnection("offline"); }
  }, []);
  useEffect(() => {
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      await sync(AbortSignal.any([controller.signal, AbortSignal.timeout(6000)]));
      if (!controller.signal.aborted) timer = setTimeout(poll, 3000);
    };
    void poll();
    return () => { controller.abort(); clearTimeout(timer); };
  }, [sync]);

  const chart = snapshot && now ? learningProgressChart(snapshot.states, snapshot.events, groups, now) : null;
  const today = now ? new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Berlin" }).format(now) : "";
  const rest = plan.breaks.find(pause => today >= pause.start && today <= pause.end);
  const next = snapshot ? plan.weeks.flatMap(week => [...week.days, ...(week.german ? [week.german] : [])]).find(day => day.lessonIds.some(id => !snapshot.states[id]?.practiced)) : null;
  const nextWeek = next ? plan.weeks.find(week => week.days.some(day => day.id === next.id) || week.german?.id === next.id)?.number : null;
  const nextHref = next?.core ? `/learning-lab#${next.id}` : `/career#week-${nextWeek ?? 1}`;
  const ceiling = Math.max(4, ...chart?.history.map(point => point.completed) ?? []);
  const points = chart?.history.map((point, i) => `${28 + i * 30},${118 - point.completed / ceiling * 90}`).join(" ") ?? "";

  return <section className="learning-overview" lang="de" dir="ltr" aria-labelledby="learning-overview-title">
    <header className="learning-overview-heading"><div><p className="learning-overview-eyebrow">DEIN LERNWEG</p><h1 id="learning-overview-title">Jede eigene Übung zählt.</h1><p>Hier siehst du, was du schon geschafft hast und welcher kleine Schritt als Nächstes ansteht.</p></div><span className={`learning-connection ${connection}`} role="status">{connection === "live" ? "● Lernstand live verbunden" : connection === "loading" ? "Lernstand wird geladen …" : snapshot ? "Verbindung unterbrochen · letzter geladener Stand" : "Lernspeicher nicht erreichbar"}</span></header>
    {!chart ? <div className="learning-overview-wait"><p>{connection === "loading" ? "Deine tatsächlichen Übungsnachweise werden geladen." : "Öffne OPEN-STUDY-WORKSPACE.cmd. Ohne Verbindung werden keine Fortschrittswerte angezeigt."}</p><Link href="/career">Zum Lernplan →</Link></div> : <>
      <div className="learning-overview-grid">
        <article className="learning-overview-total"><div className="learning-ring"><svg viewBox="0 0 160 160" role="img" aria-label={`${chart.completed} von ${chart.total} Aufgaben erledigt, ${chart.percent} Prozent`}><circle className="learning-ring-base" cx="80" cy="80" r="68" /><circle className="learning-ring-fill" cx="80" cy="80" r="68" pathLength="100" strokeDasharray={`${chart.completed / chart.total * 100} 100`} transform="rotate(-90 80 80)" /></svg><div aria-hidden="true"><strong>{chart.completed}</strong><span>von {chart.total}</span></div></div><h2>{chart.completed === 0 ? "Dein erster Nachweis macht den Anfang." : `${chart.completed} ${chart.completed === 1 ? "Aufgabe" : "Aufgaben"} selbst bearbeitet.`}</h2><p>{chart.completed === 0 ? "Beginne mit einer kleinen eigenen Antwort. Nach der Prüfung wird dein Fortschritt hier sichtbar." : `Dein letzter Übungsnachweis: ${chart.lastPractice ? shortDate(chart.lastPractice) : "Datum nicht verfügbar"}. Du kannst auf diesen Ergebnissen aufbauen.`}</p></article>
        <article className="learning-overview-tracks"><h2>Drei Bereiche, dein Fortschritt</h2>{chart.tracks.map(track => <div className={`learning-track ${track.id}`} key={track.id}><div><Link href={track.href}>{track.title}</Link><strong>{track.completed} / {track.total}</strong></div><progress max={track.total} value={track.completed} aria-label={`${track.title}: ${track.completed} von ${track.total}`} /></div>)}<p className="learning-overview-note">Grün zeigt bearbeitete Übungen mit Nachweis. Deutschwochen brauchen eigene Sprachproben und Rückmeldung. Die Zähler messen kein Sprach- oder Fachniveau.</p></article>
        <article className="learning-overview-history"><h2>Dein Weg in den letzten 14 Tagen</h2><p>{chart.hasPracticeHistory ? "Erledigte Aufgaben im Zeitverlauf. Eine Korrektur kann den Stand wieder senken." : "Noch keine Übung erfasst. Die erste geprüfte Arbeit ist dein erster Punkt im Verlauf."}</p><svg viewBox="0 0 440 148" role="img" aria-label="Verlauf erledigter Aufgaben über 14 Tage. Die genauen Werte stehen in der Tabelle darunter."><line x1="28" y1="118" x2="418" y2="118" className="learning-chart-grid" /><line x1="28" y1="28" x2="418" y2="28" className="learning-chart-grid" /><text x="8" y="122">0</text><text x="8" y="32">{ceiling}</text><polyline points={points} fill="none" className={chart.hasPracticeHistory ? "learning-chart-line" : "learning-chart-empty"} />{chart.history.filter(point => point.completed > 0).length > 0 && <circle cx="418" cy={118 - chart.history.at(-1)!.completed / ceiling * 90} r="4" className="learning-chart-dot" />}<text x="28" y="141">{shortDate(chart.history[0].day)}</text><text x="418" y="141" textAnchor="end">{shortDate(chart.history.at(-1)!.day)}</text></svg><details><summary>Verlauf als Tabelle anzeigen</summary><table><caption>Erledigte Aufgaben am jeweiligen Tagesende; heute der aktuelle Stand</caption><thead><tr><th scope="col">Tag</th><th scope="col">Erledigt</th></tr></thead><tbody>{chart.history.map(point => <tr key={point.day}><td>{shortDate(point.day)}</td><td>{point.completed}</td></tr>)}</tbody></table></details></article>
      </div>
      <div className="learning-overview-next"><div><span>{rest ? "Erholung gehört zum Plan" : chart.completed === chart.total ? "Zeit, deine Arbeit zu zeigen" : "DEIN NÄCHSTER KLEINER SCHRITT"}</span><h2>{rest ? `Ruhephase bis ${shortDate(rest.end)}` : next?.title ?? "Deine Ergebnisse prüfen und präsentieren"}</h2><p>{rest ? "Keine Nachholpflicht und keine zusätzlichen Deutschaufgaben. Dein bisheriger Fortschritt bleibt erhalten." : next?.action ?? "Vergleiche deine eigenen Arbeiten und hole Rückmeldung ein. Ein voller Lernplan ist keine Einstellungsgarantie."}</p></div><Link href={rest ? "/career" : nextHref}>{rest ? "Plan ansehen" : "Nächste Übung öffnen"} →</Link></div>
      <p className="learning-overview-note">Automatisch aus dem gemeinsamen Lernspeicher. Pausen brauchen keine Serie und bringen keine Strafpunkte. <Link href="/career">Gesamten Sechsmonatsplan öffnen</Link></p>
    </>}
  </section>;
}
